package com.deepank.careerraft.discovery;
import com.deepank.careerraft.domain.Job;import org.jsoup.Jsoup;import org.jsoup.nodes.Document;import org.jsoup.nodes.Element;import org.springframework.stereotype.Component;import java.net.URI;import java.util.*;
@Component public class CareerPageJobSource implements JobSource{
 private final SimpleHttpClient http;private final SourceConfigLoader config;private final HtmlJobParser parser;public CareerPageJobSource(SimpleHttpClient h,SourceConfigLoader c,HtmlJobParser p){http=h;config=c;parser=p;}public String provider(){return "career_page";}
 public List<Job>fetch(SourceDefinition d){String listUrl=String.valueOf(d.options().get("list_url")),prefix=String.valueOf(d.options().get("job_path_prefix")),company=d.identifier();int max=Integer.parseInt(String.valueOf(d.options().getOrDefault("max_detail_requests",8)));List<String>keywords=stringList(d.options().get("title_keywords"));Document doc=Jsoup.parse(http.getText(listUrl,"text/html,application/xhtml+xml,*/*"),listUrl);Set<String>urls=new LinkedHashSet<>();for(Element a:doc.select("a[href]")){String u=a.absUrl("href");if(matches(u,listUrl,prefix)&&allowed(a.text(),keywords))urls.add(u);if(urls.size()>=max)break;}List<Job>out=new ArrayList<>();for(String u:urls)try{Map<String,String>s=parser.extract(http.getText(u,"text/html,application/xhtml+xml,*/*"));if(s==null||s.getOrDefault("description","").length()<100)continue;String id=URI.create(u).getPath().replaceAll("/$","");id=id.substring(id.lastIndexOf('/')+1);out.add(new Job(SourceSupport.jobId(d.name(),id),d.name(),id,s.getOrDefault("company",company),s.getOrDefault("title","Software Engineer"),u,s.getOrDefault("description",""),s.get("location"),null,s.get("employment_type"),s.get("salary_text"),null,null));}catch(Exception ignored){}return out;}
 private boolean matches(String u,String list,String prefix){try{URI a=URI.create(u),b=URI.create(list);return Set.of("http","https").contains(a.getScheme())&&a.getHost().equalsIgnoreCase(b.getHost())&&a.getPath().startsWith(prefix);}catch(Exception e){return false;}}private boolean allowed(String t,List<String>k){return k.isEmpty()||k.stream().anyMatch(x->t.toLowerCase(Locale.ROOT).contains(x.toLowerCase(Locale.ROOT)));}private List<String>stringList(Object o){if(o instanceof List<?>l)return l.stream().map(String::valueOf).toList();return o==null?List.of():List.of(String.valueOf(o));}
}
